$user=fleet_cert_require_user();if(!in_array('ADMIN',$user['roles']??[],true)){http_response_code(403);exit('Only an Admin can run the initial Google sign-in setup.');}$db=fleet_db();$enabled=filter_var((string)$db->query("SELECT setting_value FROM system_settings WHERE setting_key='google_workspace_signin_enabled'")->fetchColumn(),FILTER_VALIDATE_BOOLEAN);$controllerReady=(int)$db->query("SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.role_name='APP_CONTROLLER' AND u.controller_otp_enabled_at IS NOT NULL")->fetchColumn();if($enabled||$controllerReady>0){header('Location: index.php',true,302);exit;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Google sign-in setup | FleetDesk</title><link rel="stylesheet" href="assets/css/app.css?v=31"><link rel="stylesheet" href="assets/css/certificates.css?v=22"></head><body><main class="content" style="max-width:900px"><div class="heading"><div><label>ONE-TIME SECURITY SETUP</label><h1>Configure Google sign-in</h1><p>This limited setup page lets an Admin configure the initial SSO connection. Once enabled, Settings and role management belong to the App Controller.</p></div><button class="btn" id="setupSignOut" type="button">Sign out</button></div><section class="panel"><div class="panelhead"><div><h2>Google OAuth client</h2><p>Create a Web application OAuth client in Google Cloud Console and register the callback URL below.</p></div></div><form id="googleBootstrapForm" class="cert-form"><label class="cert-sheet-sync-setting"><input type="checkbox" name="require_workspace_domain" value="1" checked><span><b>Restrict sign-in to this Workspace domain</b><small>Turn this off to allow other verified Google accounts. Accounts without an assigned role still cannot work in FleetDesk.</small></span></label><label>Workspace domain<input name="domain" placeholder="harvestgl.net"></label><label>OAuth web client ID<input name="client_id" autocomplete="off" required></label><label>OAuth web client secret<input name="client_secret" type="password" autocomplete="new-password" required></label><label>Authorized callback URL<input name="redirect_uri" type="url" required></label><p class="hint">The callback must match exactly in Google Cloud Console. The client secret is encrypted and stored outside the public app directory.</p><label class="cert-sheet-sync-setting"><input type="checkbox" name="enable" value="1"><span><b>Enable Google sign-in now</b><small>Enabling this disables username/password sign-in for everyone.</small></span></label><button class="btn primary">Save Google sign-in setup</button><span id="googleBootstrapMessage" role="status"></span></form></section></main><script src="assets/js/session-timeout.js?v=1"></script><script>document.querySelector('#setupSignOut')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;b.textContent='Signing out…';try{const r=await fetch('api/certificate-auth.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({action:'logout'})}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.message||'Sign out could not be completed.');location.replace('login.php')}catch(err){b.disabled=false;b.textContent='Sign out';document.querySelector('#googleBootstrapMessage').textContent=err.message||'Sign out could not be completed.'}});const domainToggle=document.querySelector('[name=require_workspace_domain]'),domainInput=document.querySelector('[name=domain]');domainInput.required=domainToggle.checked;domainToggle.addEventListener('change',()=>domainInput.required=domainToggle.checked);document.querySelector('[name=redirect_uri]').value=location.origin+location.pathname.replace(/[^/]*$/,'')+'api/google-auth.php?action=callback';document.querySelector('#googleBootstrapForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;const d=Object.fromEntries(new FormData(f));d.enable=f.elements.enable.checked;d.require_workspace_domain=f.elements.require_workspace_domain.checked;try{const r=await fetch('api/google-oauth-bootstrap.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify(d)}),v=await r.json();if(!r.ok||!v.ok)throw Error(v.message||'Could not save Google sign-in setup.');document.querySelector('#googleBootstrapMessage').textContent=v.message;location.replace('index.php')}catch(x){document.querySelector('#googleBootstrapMessage').textContent=x.message;b.disabled=false}})</script></body></html>
